-- =============================================================================
-- 538 — LE CAHIER D'EXERCICES DE 1RE (partie 26)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 538 --niveau 1re --fichiers ingenierie-dd.n2,innovation-technologique.n1,latin.jumelles,llcer-anglais.n1 --suffixe 26 > supabase/contenu/538_exercices_1re_26.sql
--
-- 72 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   ingenierie-dd.n2        21 exercices · 7 chapitres
--   innovation-technologique.n1  33 exercices · 11 chapitres
--   latin.jumelles           9 exercices · 3 chapitres
--   llcer-anglais.n1         9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('78026717-215f-50ff-b79b-bcd211216572'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le réseau de la maison de Lucie","competence":"observer-schema","situation":"Lucie a branché tous les appareils de sa maison sur un seul équipement. Elle dessine son réseau local pour expliquer le fonctionnement à son frère.","documents":[{"id":"etoile","type":"schema","titre":"Le réseau de la maison","largeur":340,"hauteur":270,"source":"Schéma écrit pour l’exercice","elements":[{"forme":"rect","x":125,"y":105,"l":90,"h":40,"arrondi":6,"teinte":"gris","motif":"clair","texte":"Commutateur","id":"z1","zone":true},{"forme":"rect","x":125,"y":15,"l":90,"h":40,"arrondi":6,"teinte":"gris","motif":"clair","texte":"Box","id":"z2","zone":true},{"forme":"rect","x":10,"y":105,"l":80,"h":40,"arrondi":6,"teinte":"gris","motif":"clair","texte":"Caméra","id":"z3","zone":true},{"forme":"rect","x":250,"y":105,"l":80,"h":40,"arrondi":6,"teinte":"gris","motif":"clair","texte":"Thermostat","id":"z4","zone":true},{"forme":"rect","x":125,"y":195,"l":90,"h":40,"arrondi":6,"teinte":"gris","motif":"clair","texte":"Ordinateur","id":"z5","zone":true},{"forme":"ligne","de":[170,55],"a":[170,105],"epaisseur":2},{"forme":"ligne","de":[90,125],"a":[125,125],"epaisseur":2},{"forme":"ligne","de":[215,125],"a":[250,125],"style":"pointilles","epaisseur":2},{"forme":"ligne","de":[170,145],"a":[170,195],"epaisseur":2},{"forme":"texte","x":170,"y":258,"texte":"Trait plein : câble. Pointillés : Wi-Fi.","taille":"petit","italique":true,"ancre":"milieu"}]}],"questions":[{"enonce":"Touche l’équipement central, celui auquel tous les autres sont reliés.","aide":"C’est lui qui a un trait vers chacun des autres.","type":"zone","document":"etoile","multiple":false},{"enonce":"Touche l’équipement relié **sans fil**.","aide":"Cherche le trait pointillé.","type":"zone","document":"etoile","multiple":false},{"enonce":"Combien de liaisons le schéma compte-t-il ?","aide":"Compte les traits.","type":"nombre"},{"enonce":"Le commutateur tombe en panne. Que se passe-t-il pour ce réseau en étoile ?","aide":"Que reste-t-il comme chemin entre deux appareils ?","type":"choix","options":[{"id":"a","texte":"Rien : les appareils se parlent directement"},{"id":"b","texte":"Seule la box reste isolée"},{"id":"c","texte":"Seul le thermostat Wi-Fi est coupé"},{"id":"d","texte":"Tous les appareils sont coupés les uns des autres"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **commutateur** est au centre : le réseau est en **étoile**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Le **thermostat** est relié en Wi-Fi, ce qui est indiqué par les pointillés."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"Quatre appareils, quatre liaisons vers le commutateur : **4**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Dans une topologie en étoile, si le centre tombe, **tout est coupé**."}]$ex$::jsonb),
  ('78026717-215f-50ff-b79b-bcd211216572'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui peut parler à qui ?","competence":"lire-tableau","situation":"Dans un petit immeuble, la box, une caméra, un thermostat et une borne de recharge sont reliés. Tous utilisent le masque 255.255.255.0. L’installateur dresse la liste des adresses.","documents":[{"id":"ip","type":"tableau","titre":"Adresses IP de l’immeuble","colonnes":["Équipement","Adresse IP","Masque"],"lignes":[["Box","192.168.1.1","255.255.255.0"],["Caméra","192.168.1.20","255.255.255.0"],["Thermostat","192.168.1.35","255.255.255.0"],["Borne de recharge","192.168.2.12","255.255.255.0"]],"enteteLignes":true,"source":"Adresses écrites pour l’exercice"}],"questions":[{"enonce":"Touche les adresses des deux équipements qui sont dans le même réseau que la box.","aide":"Avec ce masque, les trois premiers octets désignent le réseau.","type":"zone","document":"ip","multiple":true},{"enonce":"Quel est le dernier octet de l’adresse de la caméra, c’est-à-dire le numéro de la machine dans son réseau ?","aide":"Avec 255.255.255.0, c’est le dernier octet qui désigne la machine.","type":"texte","placeholder":"nombre"},{"enonce":"Pour que la borne de recharge et la caméra communiquent, il faut…","aide":"Sont-elles dans le même réseau ?","type":"choix","options":[{"id":"a","texte":"Un câble direct entre les deux équipements"},{"id":"b","texte":"Rien : deux machines du même immeuble se parlent toujours"},{"id":"c","texte":"Un second masque identique sur chaque équipement"},{"id":"d","texte":"Un routeur entre leurs deux réseaux"}],"multiple":false},{"enonce":"Relie chaque serveur à son rôle.","aide":"Pense à ce que chacun fournit au client.","type":"association","gauche":[{"id":"g0","texte":"DHCP"},{"id":"g1","texte":"DNS"},{"id":"g2","texte":"Serveur web"}],"droite":[{"id":"d0","texte":"Attribuer automatiquement une adresse IP"},{"id":"d1","texte":"Envoyer les pages demandées"},{"id":"d2","texte":"Traduire un nom en adresse IP"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1","r2c1"]},"explication":"La box est dans le réseau **192.168.1** ; la caméra et le thermostat aussi. La borne est dans 192.168.2."},{"cle":{"type":"texte","acceptes":["20"]},"affichage":"20","explication":"Dans 192.168.1.**20**, le dernier octet désigne la machine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Réseaux différents (192.168.1 et 192.168.2) : seul un **routeur** les relie."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**DHCP** attribue les adresses, **DNS** traduit les noms, le **serveur web** envoie les pages."}]$ex$::jsonb),
  ('78026717-215f-50ff-b79b-bcd211216572'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La mise à jour de la serrure connectée","competence":"raisonner","situation":"Léa veut ouvrir sa serrure connectée depuis son téléphone. La requête traverse toutes les couches du modèle OSI. Le soir, une mise à jour de 1,5 Mo est aussi envoyée à la serrure par Wi-Fi.","documents":[{"id":"osi","type":"tableau","titre":"Les couches traversées","colonnes":["N°","Couche","Ce qu’elle manipule"],"lignes":[[7,"Application","La requête « ouvrir la serrure »"],[6,"Présentation","Le format et le chiffrement"],[5,"Session","L’ouverture du dialogue"],[4,"Transport","Les segments (TCP)"],[3,"Réseau","Les paquets et les adresses IP"],[2,"Liaison","Les trames et les adresses MAC"],[1,"Physique","Les bits sur l’onde ou le câble"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"},{"id":"wifi","type":"tableau","titre":"La mise à jour","colonnes":["Donnée","Valeur"],"lignes":[["Taille du fichier","1,5 Mo"],["Débit de la liaison Wi-Fi","6 Mbit/s"]],"enteteLignes":true,"source":"Valeurs écrites pour l’exercice"}],"questions":[{"enonce":"Touche la couche où travaille un routeur, celle de l’adresse IP.","aide":"Le routeur relie des réseaux et regarde l’adresse IP.","type":"zone","document":"osi","multiple":false},{"enonce":"Relie chaque élément à sa couche.","aide":"Utilise la dernière colonne du tableau.","type":"association","gauche":[{"id":"g0","texte":"Adresse MAC"},{"id":"g1","texte":"Adresse IP"},{"id":"g2","texte":"Segments TCP"},{"id":"g3","texte":"Bits sur l’onde"}],"droite":[{"id":"d0","texte":"Réseau"},{"id":"d1","texte":"Physique"},{"id":"d2","texte":"Liaison"},{"id":"d3","texte":"Transport"}]},{"enonce":"Range, dans l’ordre où l’encapsulation les traite à l’envoi, ces quatre couches.","aide":"À l’envoi, les données descendent du haut vers le bas du tableau.","type":"ordre","items":[{"id":"a","texte":"Réseau"},{"id":"b","texte":"Transport"},{"id":"c","texte":"Physique"},{"id":"d","texte":"Application"}]},{"enonce":"Combien de mégabits contient le fichier de 1,5 Mo ? (1 octet = 8 bits.)","aide":"Multiplie par 8.","type":"nombre","unite":"Mbit"},{"enonce":"Combien de temps l’envoi dure-t-il ?","aide":"Durée = taille en bits ÷ débit.","type":"nombre","unite":"s"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r4c1"]},"explication":"L’adresse IP appartient à la couche **Réseau** (3), celle des routeurs."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"MAC : **liaison** (2) ; IP : **réseau** (3) ; TCP : **transport** (4) ; bits : **physique** (1)."},{"cle":{"type":"ordre","ids":["d","b","a","c"]},"explication":"À l’envoi, la requête **descend** : application, transport, réseau, puis physique ; chaque couche ajoute son en-tête."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 Mbit","explication":"1,5 × 8 = **12 Mbit**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0.01},"affichage":"2 s","explication":"12 Mbit ÷ 6 Mbit/s = **2 s**."}]$ex$::jsonb),
  ('20fb3674-96a8-5c92-8c84-e16aa5abe964'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Mesurer le moteur du drone","competence":"modeliser","situation":"Pour modéliser le moteur de son drone, Rayan le branche sur la batterie avec un ampèremètre et un voltmètre. Il relève la tension et l’intensité.","documents":[{"id":"cir","type":"circuit","titre":"Mesures sur le moteur d’un drone","branches":[{"de":[0,4],"a":[0,0],"composant":"pile"},{"de":[0,0],"a":[4,0],"composant":"interrupteur-ferme"},{"de":[4,0],"a":[8,0],"composant":"amperemetre","id":"z1","nom":"A"},{"de":[8,0],"a":[8,4],"composant":"moteur","id":"z2"},{"de":[8,0],"a":[12,0]},{"de":[12,0],"a":[12,4],"composant":"voltmetre","id":"z3","nom":"V"},{"de":[12,4],"a":[8,4]},{"de":[8,4],"a":[0,4]}]},{"id":"rel","type":"tableau","titre":"Relevés","colonnes":["Grandeur","Valeur"],"lignes":[["Tension aux bornes du moteur (V)",12],["Intensité dans le moteur (A)",4.5]],"enteteLignes":true,"source":"Relevés écrits pour l’exercice"}],"questions":[{"enonce":"Touche l’appareil qui mesure l’**intensité** du courant dans le moteur.","aide":"Il se place en série, dans la même branche que le moteur.","type":"zone","document":"cir","multiple":false},{"enonce":"Touche l’appareil monté **en dérivation** aux bornes du moteur.","aide":"Il est branché en parallèle, sur les deux bornes du moteur.","type":"zone","document":"cir","multiple":false},{"enonce":"Quelle puissance électrique le moteur absorbe-t-il ?","aide":"En électrique, la puissance est le produit de l’effort par le flux.","type":"nombre","unite":"W"},{"enonce":"Relie chaque grandeur à son rôle dans un modèle multiphysique.","aide":"Le produit effort × flux donne une puissance.","type":"association","gauche":[{"id":"g0","texte":"Tension U"},{"id":"g1","texte":"Intensité I"},{"id":"g2","texte":"Force F"},{"id":"g3","texte":"Vitesse v"}],"droite":[{"id":"d0","texte":"Effort en translation"},{"id":"d1","texte":"Effort électrique"},{"id":"d2","texte":"Flux en translation"},{"id":"d3","texte":"Flux électrique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"L’**ampèremètre** se monte en série : tout le courant du moteur le traverse."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **voltmètre** se place en dérivation pour mesurer la tension."},{"cle":{"type":"nombre","valeur":54,"tolerance":0.1},"affichage":"54 W","explication":"P = U × I = 12 × 4.5 = **54 W**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**U × I** et **F × v** sont deux puissances : U et F sont des efforts, I et v des flux."}]$ex$::jsonb),
  ('20fb3674-96a8-5c92-8c84-e16aa5abe964'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le démarrage du moteur de portail","competence":"lire-graphique","situation":"Un bureau d’études simule le courant de démarrage du moteur d’un portail, puis le mesure sur le prototype. Il compare les deux courbes pour savoir si son modèle est fiable.","documents":[{"id":"g","type":"graphique","forme":"courbe","titre":"Courant du moteur après la mise sous tension","categories":["0 s","0,1 s","0,2 s","0,3 s","0,4 s","0,5 s","0,6 s"],"series":[{"nom":"Simulation","valeurs":[12,7.13,4.64,3.35,2.69,2.36,2.18],"teinte":"violet"},{"nom":"Mesure","valeurs":[11,7.6,5.3,3.9,3,2.5,2.3],"teinte":"corail"}],"axeY":{"titre":"Courant","unite":"A","min":0,"max":12,"pas":2},"axeX":{"titre":"Temps"},"valeurs":false,"source":"Courbes simplifiées, écrites pour l’exercice"}],"questions":[{"enonce":"Quel courant de démarrage la simulation annonce-t-elle à l’instant 0 ?","aide":"Lis la première valeur de la courbe de simulation.","type":"nombre","unite":"A"},{"enonce":"Touche l’instant où la mesure et la simulation s’écartent le plus, parmi 0,1 s, 0,2 s et 0,3 s.","aide":"Compare l’écart vertical entre les deux courbes à chaque instant.","type":"zone","document":"g","multiple":false},{"enonce":"Quel est l’écart entre la mesure et la simulation à 0,2 s ? (La simulation vaut exactement 4,64 A.)","aide":"Écart = mesure − simulation.","type":"nombre","unite":"A"},{"enonce":"La mesure décroît plus lentement que la simulation. Que suggère cet écart ?","aide":"Un écart entre modèle et réel met d’abord en cause le modèle.","type":"choix","options":[{"id":"a","texte":"La simulation est inutile : on préfère désormais tout tester en réel"},{"id":"b","texte":"Le moteur du prototype est défectueux : il faut le changer sans attendre"},{"id":"c","texte":"L’inertie ou les frottements sont sous-estimés : on recale ces paramètres"},{"id":"d","texte":"Le voltmètre donne une mesure fausse : on garde donc la simulation"}],"multiple":false},{"enonce":"On réduit le pas de calcul de 0,1 s à 0,01 s. Quelle est la conséquence ?","aide":"Pense au compromis précision / temps.","type":"choix","options":[{"id":"a","texte":"Le résultat est moins précis, mais le calcul est plus rapide"},{"id":"b","texte":"Le résultat est identique, car le modèle ne change pas"},{"id":"c","texte":"Le résultat est plus précis, mais le calcul est plus long"},{"id":"d","texte":"Le calcul devient impossible, car le pas est trop petit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":12,"tolerance":0.3},"affichage":"12 A","explication":"La simulation part de **12 A** à la mise sous tension."},{"cle":{"type":"zone","ids":["k2"]},"explication":"À **0,2 s**, la mesure (5,3 A) dépasse la simulation (4.64 A) de 0.66 A, l’écart le plus grand."},{"cle":{"type":"nombre","valeur":0.66,"tolerance":0.05},"affichage":"0,66 A","explication":"5,3 − 4.64 = **0.66 A**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le modèle est trop optimiste : on **recale ses paramètres** (inertie, frottements) avant de conclure sur le produit."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un pas plus petit calcule plus de points : **plus précis, plus long**."}]$ex$::jsonb),
  ('20fb3674-96a8-5c92-8c84-e16aa5abe964'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le monte-charge du chantier","competence":"modeliser","situation":"Une entreprise de bâtiment simule le moteur d’un monte-charge. Le treuil soulève une charge de 800 N à 0,25 m/s. Le moteur a un rendement de 0,8 et il est alimenté en 25 V.","documents":[{"id":"dat","type":"tableau","titre":"Données du monte-charge","colonnes":["Donnée","Valeur"],"lignes":[["Force exercée par le câble (N)",800],["Vitesse de montée (m/s)",0.25],["Rendement du moteur",0.8],["Tension d’alimentation (V)",25]],"enteteLignes":true,"source":"Données écrites pour l’exercice"}],"questions":[{"enonce":"Classe ces éléments du modèle de simulation.","aide":"Les paramètres décrivent les constituants ; les entrées sont imposées au modèle ; les sorties sont les résultats.","type":"categories","categories":[{"id":"c0","texte":"Variable interne (paramètre)"},{"id":"c1","texte":"Variable externe (entrée)"},{"id":"c2","texte":"Sortie"}],"items":[{"id":"i0","texte":"Courbe du courant relevée"},{"id":"i1","texte":"Consigne de vitesse"},{"id":"i2","texte":"Tension d’alimentation"},{"id":"i3","texte":"Masse de la cabine"},{"id":"i4","texte":"Résistance du moteur"}]},{"enonce":"Quelle puissance mécanique le treuil fournit-il à la charge ?","aide":"En translation, P = F × v.","type":"nombre","unite":"W"},{"enonce":"Quelle puissance électrique le moteur absorbe-t-il ?","aide":"Rendement = puissance utile ÷ puissance absorbée.","type":"nombre","unite":"W"},{"enonce":"Quelle intensité le moteur appelle-t-il ?","aide":"En électrique, P = U × I.","type":"nombre","unite":"A"},{"enonce":"La mesure donne 11,5 A au lieu de 10 A. Que fait-on ?","aide":"Un écart modèle / réel conduit d’abord à corriger les hypothèses du modèle.","type":"choix","options":[{"id":"a","texte":"On supprime la consigne de vitesse de ce modèle de simulation"},{"id":"b","texte":"On change le moteur directement, sans aucune autre vérification"},{"id":"c","texte":"On recale le modèle, par exemple le rendement ou les frottements"},{"id":"d","texte":"On ignore la mesure, car on estime que la simulation fait foi"}],"multiple":false}]}$ex$::jsonb,
