ut Inès sur la longueur du bras de levier ?","aide":"Compare 120 N à 0,35 m avec la force à 0,5 m.","type":"choix","options":[{"id":"a","texte":"Plus il est grand, plus la force nécessaire est petite"},{"id":"b","texte":"Plus il est grand, plus la force nécessaire est grande"},{"id":"c","texte":"La longueur du bras n’a aucune influence"},{"id":"d","texte":"Seule la position de l’écrou compte"}],"multiple":false}]}$ex$::jsonb,
