   $ex${"titre":"Le casque audio prend du retard","competence":"modeliser","situation":"L’équipe d’un casque audio sans fil a planifié sa pré-conception. En revue de projet, un fournisseur annonce un retard : l’équipe doit mesurer l’effet sur la date de fin.","documents":[{"id":"plan","type":"tableau","titre":"Le planning prévu","colonnes":["Tâche","Durée (jours)","Antériorité"],"lignes":[["A : étude de marché",3,"—"],["B : cahier des charges",2,"A"],["C : choix des transducteurs",4,"B"],["D : conception du boîtier",6,"B"],["E : prototype",5,"C et D"],["F : essais",3,"E"]],"enteteLignes":true,"source":"Durées inventées pour l’exercice"},{"id":"revue","type":"fiche","modele":"affiche","entete":"Revue de projet n° 2","sousTitre":"Casque audio — fin de la pré-conception","emoji":"🎧","lignes":[{"texte":"Tâche C : transducteurs livrés avec 3 jours de retard","id":"z1"},{"separateur":true},{"texte":"Décision attendue du jalon : continuer, corriger ou arrêter"}],"pied":"Document écrit pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Quelle est la durée minimale du projet prévu, en jours ?","aide":"Compare A → B → C → E → F et A → B → D → E → F.","type":"nombre","unite":"jours"},{"enonce":"Quelle marge possède la tâche C, en jours ?","aide":"C et D doivent toutes deux être finies pour lancer E : compare leurs durées.","type":"nombre","unite":"jours"},{"enonce":"Avec le retard de 3 jours sur C, quelle devient la durée minimale du projet, en jours ?","aide":"C passe à 4 + 3 = 7 jours : recompare les deux chemins.","type":"nombre","unite":"jours"},{"enonce":"Après ce retard, quel est le chemin critique ?","aide":"Le chemin critique est le plus long après modification.","type":"choix","options":[{"id":"a","texte":"A → B → C → D → E → F, qui regroupe toutes les tâches"},{"id":"b","texte":"A → B → D → E → F, qui est resté le même"},{"id":"c","texte":"C → E → F, qui commence à la tâche en retard"},{"id":"d","texte":"A → B → C → E → F, qui est devenu le plus long"}],"multiple":false},{"enonce":"Que doit décider l’équipe à ce jalon ?","aide":"Un jalon clôt une phase par une décision.","type":"choix","options":[{"id":"a","texte":"Terminer les essais avant le prototype pour gagner du temps"},{"id":"b","texte":"Changer de client pour retrouver un budget plus élevé"},{"id":"c","texte":"Continuer, corriger le planning ou arrêter, après avoir mesuré l’écart"},{"id":"d","texte":"Ignorer le retard puisque la marge de C est de 2 jours"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 jours","explication":"Par C : 3 + 2 + 4 + 5 + 3 = 17 j. Par D : 3 + 2 + 6 + 5 + 3 = 19 j. Le projet dure au minimum **19 jours**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 jours","explication":"D dure 6 j et C 4 j : E attend la fin de D. C peut glisser de 6 − 4 = **2 jours** sans rien retarder."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 jours","explication":"C dure maintenant 7 j : A → B → C → E → F fait 3 + 2 + 7 + 5 + 3 = 20 j, contre 19 j par D. La fin recule d’**1 jour** : 20 jours."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avec 20 j, c’est **A → B → C → E → F** qui est critique : la marge de C (2 j) est dépassée de 1 j."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un jalon est une **revue de projet** : on décide de continuer, de corriger ou d’arrêter, à partir de l’écart mesuré (ici +1 jour)."}]$ex$::jsonb),
