ion"},{"id":"i2","texte":"Savoir quelle version d’un plan a servi pour une série de casques"},{"id":"i3","texte":"Architecte et électricien consultent une même maquette 3D d’un gymnase"},{"id":"i4","texte":"Un constructeur suit les plans et nomenclatures de 2 000 pièces"}]},{"enonce":"Pour le jury, que choisit-on de montrer en priorité ?","aide":"Le jury n’est pas composé d’ingénieurs.","type":"choix","options":[{"id":"a","texte":"Un schéma simple avec les flux principaux"},{"id":"b","texte":"Un diagramme SysML complet des exigences"},{"id":"c","texte":"Le code source de toute l’application"},{"id":"d","texte":"Un tableau de toutes les versions des fichiers"}],"multiple":false}]}$ex$::jsonb,
