iple":false},{"enonce":"Quel est le coût matière d’une éprouvette de 22 g à 25 € le kilo, en euros ?","aide":"Convertis 22 g en kilogrammes.","type":"nombre","unite":"€"},{"enonce":"Range les étapes d’un essai sur prototype.","aide":"Avant de mesurer, il faut savoir quoi vérifier.","type":"ordre","items":[{"id":"a","texte":"Écrire un protocole"},{"id":"b","texte":"Conclure : conforme ou à modifier"},{"id":"c","texte":"Mesurer"},{"id":"d","texte":"Définir ce que l’on veut vérifier"},{"id":"e","texte":"Comparer au cahier des charges"}]}]}$ex$::jsonb,
