   $ex${"titre":"Je dis que Marcus vient","competence":"manier-langue","situation":"Clara découvre une construction que le français n’a pas : après un verbe de parole ou de vue, le latin met le sujet à l’accusatif et le verbe à l’infinitif.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Trois phrases","auteur":"Phrases écrites pour l’exercice","blocs":["Dico Marcum venire.","Puella dicit servum ridere.","Video puellam ridere."],"source":"Vocabulaire : dico, dicit = je dis, elle dit ; video = je vois ; venire = venir ; ridere = rire."}],"questions":[{"enonce":"Dans la phrase 1, touche le verbe de parole qui introduit la proposition infinitive.","aide":"Il signifie « je dis ».","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans la phrase 1, touche le sujet de « venire ».","aide":"Dans une infinitive, le sujet est à l’accusatif.","type":"zone","document":"phrases","multiple":false},{"enonce":"Quelle est la traduction de la phrase 1 ?","aide":"Le latin n’emploie pas « que » : c’est l’infinitive qui joue ce rôle.","type":"choix","options":[{"id":"a","texte":"Je dis à Marcus de venir."},{"id":"b","texte":"Marcus dit que je viens."},{"id":"c","texte":"Je dis Marcus venir."},{"id":"d","texte":"Je dis que Marcus vient."}],"multiple":false},{"enonce":"Complète la traduction de la phrase 2.","aide":"Le verbe de parole est dicit ; ridere est à l’infinitif.","type":"trous","segments":["Puella dicit servum ridere : la jeune fille ",0," que l’esclave ",1,"."],"banque":["voit","rient","rit","dit"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Dico** est le verbe de parole : après lui, le latin construit une proposition infinitive."},{"cle":{"type":"zone","ids":["m1"]},"explication":"**Marcum** est le sujet de venire : il est à l’accusatif, et il n’y a pas de COD ici."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Je dis que Marcus vient.** L’infinitive se traduit par une subordonnée en « que »."},{"cle":{"type":"trous","trous":[["dit"],["rit"]]},"affichage":"dit · rit","explication":"Elle **dit** que l’esclave **rit** : *servum* est le sujet de *ridere*, à l’accusatif."}]$ex$::jsonb),
  ('c4b548a6-5f6f-5513-a5ff-22ac08e37013'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Après la prise de la ville","competence":"comprendre-langue","situation":"Clara lit deux phrases du récit d’une guerre. Chacune commence par un nom et un participe à l’ablatif : c’est un ablatif absolu, qu’il faudra traduire sans mot à mot.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Deux phrases d’un récit de guerre","auteur":"Phrases écrites pour l’exercice","blocs":["Urbe capta, consul Romam rediit.","Hostibus victis, milites domum redierunt."],"source":"Vocabulaire : urbs = ville ; Romam = à Rome ; rediit = il revint ; hostes = ennemis ; milites = soldats ; domum = chez eux ; redierunt = ils revinrent."},{"id":"part","type":"tableau","titre":"Les participes","colonnes":["Participe","Finale","Exemple","Sens"],"lignes":[["Présent actif","-ns, -ntis","amans","aimant"],["Parfait passif","-tus, -a, -um","amatus","ayant été aimé"],["Futur actif","-turus","amaturus","devant aimer"],["Adjectif verbal","-ndus","amandus","qui doit être aimé"]]}],"questions":[{"enonce":"Dans la phrase 1, touche les deux mots de l’ablatif absolu.","aide":"L’ablatif absolu est un nom et un participe, sans lien grammatical avec la principale.","type":"zone","document":"phrases","multiple":true},{"enonce":"Comment traduire naturellement « Hostibus victis » dans la phrase 2 ?","aide":"L’ablatif absolu devient un complément circonstanciel de temps.","type":"choix","options":[{"id":"a","texte":"Contre les ennemis vaincus"},{"id":"b","texte":"Une fois les ennemis vaincus"},{"id":"c","texte":"Pour vaincre les ennemis"},{"id":"d","texte":"Les ennemis vainqueurs"}],"multiple":false},{"enonce":"Touche, dans le tableau, la forme qui signifie « devant aimer ».","aide":"Cherche la ligne du futur actif.","type":"zone","document":"part","multiple":false},{"enonce":"Voici des participes d’autres verbes. Classe-les d’après leur finale.","aide":"Cherche -ns, -tus ou -turus.","type":"categories","categories":[{"id":"c0","texte":"Présent actif"},{"id":"c1","texte":"Parfait passif"},{"id":"c2","texte":"Futur actif"}],"items":[{"id":"i0","texte":"docturus"},{"id":"i1","texte":"docens"},{"id":"i2","texte":"monitus"},{"id":"i3","texte":"doctus"},{"id":"i4","texte":"monens"},{"id":"i5","texte":"moniturus"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1"]},"explication":"**Urbe capta** est l’ablatif absolu : « la ville ayant été prise », c’est-à-dire « après la prise de la ville »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Une fois les ennemis vaincus** : le français rend l’ablatif absolu par une circonstancielle, jamais mot à mot."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"**Amaturus** est le participe futur actif : « devant aimer »."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c2"}},"explication":"Les finales sont les mêmes que dans le tableau : **-ns** (présent), **-tus** (parfait passif), **-turus** (futur)."}]$ex$::jsonb),
  ('c4b548a6-5f6f-5513-a5ff-22ac08e37013'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Delenda est Carthago","competence":"analyser-texte","situation":"Rome, IIe siècle av. J.-C. : Caton l’Ancien terminait ses discours par une formule restée célèbre. Tu analyses ses deux versions, puis tu situes la ville visée.","documents":[{"id":"caton","type":"texte","genre":"source","titre":"La formule de Caton","blocs":["Carthago delenda est.","Ceterum censeo Carthaginem esse delendam."],"source":"Formules attribuées à Caton l’Ancien (IIe siècle av. J.-C.). Vocabulaire : ceterum = du reste ; censeo = je pense ; esse = être."},{"id":"carte","type":"carte","titre":"Deux villes de la Méditerranée","fond":"mediterranee","cadrage":[-2,31,22,46],"lieux":[{"id":"z1","lieu":"rome","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lieu":"carthage","symbole":"lettre","lettre":"B","teinte":"violet"}],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Dans la deuxième phrase, touche le verbe d’opinion qui introduit la proposition infinitive.","aide":"Il signifie « je pense ».","type":"zone","document":"caton","multiple":false},{"enonce":"Touche le sujet de la proposition infinitive « esse delendam ».","aide":"Dans une infinitive, le sujet est à l’accusatif.","type":"zone","document":"caton","multiple":false},{"enonce":"Quelle est la traduction de « Carthago delenda est » ?","aide":"L’adjectif verbal en -ndus exprime l’obligation.","type":"choix","options":[{"id":"a","texte":"Carthage va détruire Rome."},{"id":"b","texte":"Carthage a été détruite."},{"id":"c","texte":"Carthage détruit la ville."},{"id":"d","texte":"Carthage doit être détruite."}],"multiple":false},{"enonce":"Complète la traduction de la deuxième phrase.","aide":"C’est la même idée d’obligation que dans la première formule.","type":"trous","segments":["Du reste, je pense que Carthage ",0," être ",1,"."],"banque":["détruire","a été","détruite","peut","doit"]},{"enonce":"Caton veut voir cette ville détruite. Touche sa lettre sur la carte.","aide":"Carthage se trouve en Afrique du Nord, face à la Sicile.","type":"zone","document":"carte","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**Censeo** (« je pense ») est le verbe d’opinion : après lui, le latin met une proposition infinitive."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**Carthaginem** est le sujet de l’infinitive : il est à l’accusatif."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Carthage doit être détruite** : *delenda* est un adjectif verbal, qui exprime l’obligation."},{"cle":{"type":"trous","trous":[["doit"],["detruite"]]},"affichage":"doit · détruite","explication":"La phrase signifie : du reste, je pense que Carthage **doit** être **détruite**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Carthage (B) est en Afrique du Nord, à l’emplacement de l’actuelle Tunisie ; la lettre A marque Rome."}]$ex$::jsonb),
  ('9b960b70-4b9c-564b-92f4-b4527c413d93'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Lucius veut faire carrière","competence":"se-reperer-temps","situation":"Lucius, jeune Romain ambitieux, rêve de gouverner la République. Il doit gravir un à un les échelons du cursus honorum.","documents":[{"id":"cursus","type":"chaine","titre":"Le cursus honorum","disposition":"ligne","noeuds":[{"id":"z1","texte":"Questure","emoji":"💰"},{"id":"z2","texte":"?","emoji":"🏟️"},{"id":"z3","texte":"Préture","emoji":"⚖️"},{"id":"z4","texte":"Consulat","emoji":"🏛️"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}],"source":"Schéma écrit pour l’exercice"}],"questions":[{"enonce":"Quelle étape se cache derrière le « ? » ?","aide":"Elle suit la questure et précède la préture.","type":"choix","options":[{"id":"a","texte":"l’édilité"},{"id":"b","texte":"la censure"},{"id":"c","texte":"la dictature"},{"id":"d","texte":"l’exil"}],"multiple":false},{"enonce":"Touche la magistrature la plus haute du cursus honorum.","aide":"C’est la dernière étape de la carrière.","type":"zone","document":"cursus","multiple":false},{"enonce":"Associe chaque institution romaine à son pouvoir.","aide":"Le Sénat est composé d’anciens magistrats.","type":"association","gauche":[{"id":"g0","texte":"Le Sénat"},{"id":"g1","texte":"Les comices"},{"id":"g2","texte":"Les tribuns de la plèbe"}],"droite":[{"id":"d0","texte":"donne l’orientation politique"},{"id":"d1","texte":"disposent du droit de veto"},{"id":"d2","texte":"votent les lois et élisent"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"Le cursus honorum suit l’ordre : questure, **édilité**, préture, consulat."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Le **consulat** est le sommet de la carrière politique romaine."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Le **Sénat** oriente la politique, les **comices** votent et élisent, les **tribuns de la plèbe** peuvent opposer leur veto."}]$ex$::jsonb),
  ('9b960b70-4b9c-564b-92f4-b4527c413d93'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La République, restaurée ou récupérée ?","competence":"analyser-document","situation":"Vers 20 av. J.-C., Lucius écrit à son frère. Il lui raconte ce qu’Auguste a changé à Rome, et se demande ce qui reste de la République.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Lucius à son frère","auteur":"Lettre imaginée pour l’exercice","blocs":["Cher Marcus, les consuls sont élus comme avant, le Sénat se réunit, les comices votent. Pourtant, rien ne se décide sans Auguste. Il répète partout *res publica restituta*, « la République restaurée ». Je me demande s’il la restaure vraiment ou s’il n’en garde que le nom. Lucius"]},{"id":"frise","type":"frise","titre":"De César à Auguste","debut":-60,"fin":-20,"pas":5,"evenements":[{"id":"z1","date":-44,"nom":"Ides de mars"},{"id":"z2","date":-27,"nom":"Principat d’Auguste"}]}],"questions":[{"enonce":"Touche le mot dont Auguste affirme la restauration.","aide":"C’est le mot qui suit « restaurée » dans la formule.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’événement qui marque la naissance du pouvoir d’Auguste.","aide":"Le principat est fondé en 27 av. J.-C.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’assassinat de César (ides de mars) de la fondation du principat ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Que laisse entendre Lucius dans sa lettre ?","aide":"Lucius cite les institutions, puis dit « pourtant ».","type":"choix","options":[{"id":"a","texte":"Les comices ont obtenu un pouvoir plus grand qu’avant son arrivée"},{"id":"b","texte":"Les institutions existent encore, mais le vrai pouvoir est à Auguste"},{"id":"c","texte":"La République a été entièrement rétablie et rend le pouvoir au peuple"},{"id":"d","texte":"Les consuls et le Sénat ont été supprimés par Auguste lui-même"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"Auguste dit restaurer la **République** : *res publica restituta*, formule de communication politique."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **principat** est fondé par Auguste en 27 av. J.-C."},{"cle":{"type":"nombre","valeur":17,"tolerance":0},"affichage":"17 ans","explication":"44 − 27 = **17 ans**."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’Empire **garde les formes républicaines et en vide le contenu** : les institutions subsistent, mais le pouvoir est à Auguste."}]$ex$::jsonb),
  ('9b960b70-4b9c-564b-92f4-b4527c413d93'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Patron et client : un échange de services","competence":"analyser-document","situation":"À Rome, un sénateur et un petit artisan peuvent dépendre l’un de l’autre. Tu lis le récit d’une matinée chez le sénateur Titus, puis tu repères qui a des droits et qui n’en a pas.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Chez le sénateur Titus","auteur":"Récit imaginé pour l’exercice","blocs":["Gaius, petit artisan et citoyen romain, se rend chaque matin chez son patron, le sénateur Titus. Titus a payé ses dettes et lui a trouvé un atelier. En échange, avant l’élection des édiles, Gaius promet de voter pour le fils de Titus. À la porte, l’esclave Sôsias le fait entrer. Dans la maison, la materfamilias Livia, épouse de Titus et très respectée, dirige les servantes."]},{"id":"schema","type":"schema","titre":"Un échange entre deux hommes","largeur":340,"hauteur":190,"elements":[{"forme":"rect","x":20,"y":60,"l":90,"h":50,"arrondi":8,"texte":"Titus","id":"z1","zone":true,"teinte":"violet","motif":"clair"},{"forme":"rect","x":230,"y":60,"l":90,"h":50,"arrondi":8,"texte":"Gaius","id":"z2","zone":true,"teinte":"violet","motif":"clair"},{"forme":"ligne","de":[110,78],"a":[230,78],"fleche":"fin"},{"forme":"texte","x":170,"y":68,"texte":"protection","ancre":"milieu","taille":"petit"},{"forme":"ligne","de":[230,98],"a":[110,98],"fleche":"fin"},{"forme":"texte","x":170,"y":122,"texte":"votes et soutien","ancre":"milieu","taille":"petit"}]}],"questions":[{"enonce":"Touche le service que le client promet de rendre à son patron.","aide":"Il concerne l’élection des édiles.","type":"zone","document":"recit","multiple":false},{"enonce":"Touche celui qui reçoit la protection de l’autre.","aide":"Suis la flèche marquée « protection ».","type":"zone","document":"schema","multiple":false},{"enonce":"Associe chaque personnage à son rôle.","aide":"Le patronus est le plus puissant des deux.","type":"association","gauche":[{"id":"g0","texte":"Titus"},{"id":"g1","texte":"Gaius"},{"id":"g2","texte":"Sôsias"},{"id":"g3","texte":"Livia"}],"droite":[{"id":"d0","texte":"materfamilias : respectée, sans droits politiques"},{"id":"d1","texte":"servus : il n’est pas libre"},{"id":"d2","texte":"cliens : il soutient"},{"id":"d3","texte":"patronus : il protège"}]},{"enonce":"Classe chaque personnage selon ses droits politiques.","aide":"Le citoyen homme vote ; l’esclave et la femme ne votent pas.","type":"categories","categories":[{"id":"c0","texte":"Droits politiques"},{"id":"c1","texte":"Aucun droit politique"}],"items":[{"id":"i0","texte":"Livia, la materfamilias"},{"id":"i1","texte":"Gaius, artisan citoyen"},{"id":"i2","texte":"Sôsias, esclave"},{"id":"i3","texte":"Titus, sénateur"}]},{"enonce":"Pourquoi les clients sont-ils précieux pour un sénateur qui veut faire carrière ?","aide":"Pense aux comices, qui élisent les magistrats.","type":"choix","options":[{"id":"a","texte":"Ils paient à sa place les impôts de toute la cité"},{"id":"b","texte":"Ils siègent à sa place au Sénat pendant ses absences"},{"id":"c","texte":"Ils commandent à sa place les armées de la République"},{"id":"d","texte":"Ils votent pour lui et pour ses proches aux élections"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37"]},"explication":"Gaius promet de **voter** pour le fils de Titus : c’est son soutien en échange de la protection."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La flèche « protection » va de Titus vers **Gaius** : le client est protégé, et il rend en échange ses votes et son soutien."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Titus est le **patronus**, Gaius le **cliens**, Sôsias un **esclave** et Livia la **materfamilias**, respectée mais sans droits politiques."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"Les citoyens **Titus** et **Gaius** votent ; **Sôsias** (esclave) et **Livia** (femme) n’ont aucun droit politique."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les clients forment une base de **voix** pour le patron et sa famille : c’est le clientélisme, protection contre soutien."}]$ex$::jsonb),
  ('795921cd-11c1-5ccd-9590-25c30806702d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une frise pour l’exposition « Monsters »","competence":"se-reperer-temps","situation":"La médiathèque prépare une exposition sur les monstres de la littérature anglaise. Sam doit placer les grands romans gothiques sur une frise et ne pas confondre les dates ni les auteurs.","documents":[{"id":"frise","type":"frise","titre":"Four Gothic landmarks","debut":1750,"fin":1900,"pas":25,"evenements":[{"id":"z1","date":1764,"nom":"The Castle of Otranto"},{"id":"z2","date":1818,"nom":"Frankenstein"},{"id":"z3","date":1886,"nom":"Jekyll and Hyde"},{"id":"z4","date":1897,"nom":"Dracula"}],"source":"Dates de première publication"}],"questions":[{"enonce":"Touche **le roman qui lance le genre gothique**, le plus ancien de la frise.","aide":"Cherche le point le plus à gauche : c’est le roman publié en premier.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la publication de *Frankenstein* de celle de *Dracula* ?","aide":"Lis les deux dates sur la frise, puis soustrais la plus ancienne de la plus récente.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque roman à son auteur.","aide":"Frankenstein est le seul de la liste écrit par une autrice.","type":"association","gauche":[{"id":"g0","texte":"Frankenstein"},{"id":"g1","texte":"Dracula"},{"id":"g2","texte":"Dr Jekyll and Mr Hyde"},{"id":"g3","texte":"The Picture of Dorian Gray"}],"droite":[{"id":"d0","texte":"Bram Stoker"},{"id":"d1","texte":"Robert Louis Stevenson"},{"id":"d2","texte":"Oscar Wilde"},{"id":"d3","texte":"Mary Shelley"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"*The Castle of Otranto* (1764, Horace Walpole) est le premier roman gothique : c’est le point **le plus à gauche** de la frise."},{"cle":{"type":"nombre","valeur":79,"tolerance":0},"affichage":"79 ans","explication":"*Dracula* paraît en 1897 et *Frankenstein* en 1818 : 1897 − 1818 = **79 ans**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**Frankenstein** : Mary Shelley (1818) ; **Dracula** : Bram Stoker (1897) ; **Dr Jekyll and Mr Hyde** : Stevenson (1886) ; **Dorian Gray** : Oscar Wilde (1890)."}]$ex$::jsonb),
  ('795921cd-11c1-5ccd-9590-25c30806702d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le manuscrit de Hollowmere","competence":"analyser-texte","situation":"Le club de lecture lit un court texte gothique écrit pour l’occasion. Léa doit y retrouver les motifs du genre et repérer comment l’auteur prépare la peur.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"The Hollowmere manuscript","auteur":"Texte écrit pour l’exercice","blocs":["Nobody in Hollowmere spoke of the old castle after dark. Its ruined towers stood above the village, and the children said that a family curse kept the house empty.","One winter evening, the steward found a manuscript in the cellar. Its author was unknown, and its last page was torn. He read it by candlelight, and the portrait on the stairs seemed to watch him.","Little did he know that this was the last quiet evening of his life."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **les deux mots qui nomment les lieux clos et inquiétants** du récit.","aide":"Un château et un souterrain : cherche un bâtiment et une pièce sous le sol.","type":"zone","document":"texte","multiple":true},{"enonce":"Touche **le mot qui désigne le motif dont on ne peut pas vérifier l’origine**.","aide":"Il s’agit d’un écrit retrouvé, dont l’auteur est inconnu.","type":"zone","document":"texte","multiple":false},{"enonce":"La phrase « Little did he know that this was the last quiet evening of his life. » est un exemple de…","aide":"Le narrateur annonce discrètement ce qui va arriver.","type":"choix","options":[{"id":"a","texte":"serialisation"},{"id":"b","texte":"foreshadowing"},{"id":"c","texte":"free indirect speech"},{"id":"d","texte":"unreliable narrator"}],"multiple":false},{"enonce":"Relie chaque motif gothique à ce qu’il produit.","aide":"Pense à ce que chaque motif fait ressentir au lecteur : enfermement, retour, doute, héritage.","type":"association","gauche":[{"id":"g0","texte":"Le château, le souterrain"},{"id":"g1","texte":"Le portrait animé"},{"id":"g2","texte":"Le manuscrit retrouvé"},{"id":"g3","texte":"La malédiction familiale"}],"droite":[{"id":"d0","texte":"La faute qui se transmet"},{"id":"d1","texte":"Le passé qui revient"},{"id":"d2","texte":"L’espace clos dont on ne sort pas"},{"id":"d3","texte":"Un récit dont on ne peut vérifier l’origine"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7","m39"]},"explication":"Le **castle** et la **cellar** sont les lieux typiques du roman gothique : des espaces clos, anciens, dont on ne sort pas facilement."},{"cle":{"type":"zone","ids":["m36"]},"explication":"Le **manuscript** retrouvé est un motif classique : on ne sait pas qui l’a écrit, donc on ne peut pas vérifier le récit."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le narrateur annonce un malheur à venir sans le décrire : c’est du **foreshadowing**, l’annonce discrète d’un événement futur."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"Le **château** enferme ; le **portrait** fait revenir le passé ; le **manuscrit** rend le récit invérifiable ; la **malédiction** fait payer aux enfants la faute des parents."}]$ex$::jsonb),
  ('795921cd-11c1-5ccd-9590-25c30806702d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La lettre du créateur et le tableau des monstres","competence":"argumenter","situation":"Pour un exposé, Inès croise deux documents : une lettre imaginée dans l’esprit de *Frankenstein* et un tableau qui compare quatre monstres gothiques. Elle veut comprendre d’où vient la peur dans chaque œuvre.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"A letter from the creator","auteur":"Texte écrit pour l’exercice, à la manière de Mary Shelley","blocs":["My dear Margaret,","I have done what no man had done: I gave life to a creature made of dead matter. He opened his eyes, and I fled the room. I told myself that he would die, or vanish, or that I had dreamed him.","But he lived. He learned our language alone, in the woods, and he came back to me with no weapon except his voice. He asked for a name, a companion, a place among men. I refused him everything, and I abandoned him to the woods, and called it prudence.","I did not make him cruel. I made him alone; the cruelty came after."],"source":"Texte écrit pour l’exercice"},{"id":"tab","type":"tableau","titre":"Four Gothic monsters","colonnes":["Work","Author","Date","What the monster reveals"],"lignes":[["Frankenstein","Mary Shelley",1818,"A creature made by science"],["Dr Jekyll and Mr Hyde","R. L. Stevenson",1886,"The hidden side of a respectable man"],["The Picture of Dorian Gray","Oscar Wilde",1890,"A portrait that ages in the man’s place"],["Dracula","Bram Stoker",1897,"Fear of the foreigner and of contagion"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche **les trois mots qui montrent comment le créateur traite sa créature**.","aide":"Cherche trois verbes qui disent le rejet : fuir, refuser, laisser seul.","type":"zone","document":"lettre","multiple":true},{"enonce":"Selon la lettre, pourquoi la créature devient-elle cruelle ?","aide":"Relis la dernière phrase : « I did not make him cruel. I made him alone. »","type":"choix","options":[{"id":"a","texte":"Parce qu’elle a lu un manuscrit maudit"},{"id":"b","texte":"Parce qu’elle est née mauvaise"},{"id":"c","texte":"Parce que son créateur l’a abandonnée"},{"id":"d","texte":"Parce qu’une malédiction pèse sur sa famille"}],"multiple":false},{"enonce":"Touche **le titre de l’œuvre que cette lettre imite**.","aide":"Une créature faite de matière morte, un créateur qui s’enfuit : cherche l’œuvre où le monstre est fabriqué.","type":"zone","document":"tab","multiple":false},{"enonce":"Combien d’années séparent la publication de *Frankenstein* de celle de *The Picture of Dorian Gray* ?","aide":"Lis les deux dates dans la colonne « Date » du tableau.","type":"nombre","unite":"ans"},{"enonce":"Complète la conclusion de l’exposé d’Inès.","aide":"Reprends les mots de la lettre : le créateur « abandoned » sa créature.","type":"trous","segments":["Le monstre de Shelley ne naît pas mauvais : il le devient parce qu’il est ",0," par son créateur. Le roman pose donc la question de la ",1," du créateur."],"banque":["abandonné","responsabilité","félicité","punition","malédiction"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27","m80","m85"]},"explication":"**fled**, **refused**, **abandoned** : le créateur fuit, refuse et abandonne. C’est cet abandon qui, dans le roman, rend le monstre cruel."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le créateur dit lui-même : « I made him alone ; the cruelty came after ». La créature ne naît pas mauvaise : elle le **devient d’être abandonnée**."},{"cle":{"type":"zone","ids":["r0c0"]},"explication":"La lettre imite **Frankenstein** : une créature fabriquée à partir de matière morte, puis abandonnée par son créateur."},{"cle":{"type":"nombre","valeur":72,"tolerance":0},"affichage":"72 ans","explication":"1890 − 1818 = **72 ans**."},{"cle":{"type":"trous","trous":[["abandonne","abandonnee"],["responsabilite"]]},"affichage":"abandonné · responsabilité","explication":"Le monstre est **abandonné** par son créateur ; le roman interroge donc sa **responsabilité** : le créateur répond-il de ce qu’il a fabriqué ?"}]$ex$::jsonb),
  ('b504aa24-0f02-59e4-9167-e2d99b083b61'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La bibliothèque du club de lecture","competence":"lire-tableau","situation":"Le club de lecture du lycée a commencé une étagère de romans du XIXe siècle. Samir doit lire sa fiche récapitulative, puis relier les romans de Dickens à ce qu’ils dénoncent.","documents":[{"id":"tab","type":"tableau","titre":"Our reading list","colonnes":["Novel","Author","Year"],"lignes":[["Pride and Prejudice","Jane Austen",1813],["Jane Eyre","Charlotte Brontë",1847],["Wuthering Heights","Emily Brontë",1847]],"enteteLignes":true,"source":"Dates de première publication"}],"questions":[{"enonce":"Touche **les deux dates identiques** : deux romans sont parus la même année.","aide":"Parcours la colonne « Year » : deux cases ont la même valeur.","type":"zone","document":"tab","multiple":true},{"enonce":"Combien d’années séparent *Pride and Prejudice* de *Jane Eyre* ?","aide":"Soustrais la plus petite année de la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque roman de Dickens à ce qu’il met en accusation.","aide":"*Hard Times* signifie « temps difficiles » : pense à l’industrie.","type":"association","gauche":[{"id":"g0","texte":"Oliver Twist"},{"id":"g1","texte":"Hard Times"},{"id":"g2","texte":"Great Expectations"}],"droite":[{"id":"d0","texte":"La ville industrielle et l’utilitarisme"},{"id":"d1","texte":"L’argent qui fabrique un gentleman"},{"id":"d2","texte":"Les workhouses et le sort des orphelins"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2","r2c2"]},"explication":"*Jane Eyre* (Charlotte) et *Wuthering Heights* (Emily) paraissent **tous deux en 1847**."},{"cle":{"type":"nombre","valeur":34,"tolerance":0},"affichage":"34 ans","explication":"1847 − 1813 = **34 ans**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Oliver Twist** dénonce les workhouses ; **Hard Times** la ville industrielle et l’utilitarisme ; **Great Expectations** l’argent qui fabrique un gentleman."}]$ex$::jsonb),
  ('b504aa24-0f02-59e4-9167-e2d99b083b61'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le village de Netherby","competence":"analyser-texte","situation":"Nina étudie un texte écrit dans l’esprit des romans de Jane Austen. Elle doit y repérer l’argent, comprendre l’ironie du narrateur et revoir les notions du chapitre.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"The gentleman of Netherby","auteur":"Texte écrit pour l’exercice, à la manière de Jane Austen","blocs":["It was generally agreed in the village of Netherby that Mr Ashworth, who had lately inherited four thousand pounds a year, could not possibly remain single. Mrs Pole, who had five daughters and a very small income, agreed with the village most warmly; indeed, she had agreed with it for three weeks, which is the length of time Mr Ashworth had been in the neighbourhood.","Her eldest daughter, who was thought to have a good heart and no fortune, was therefore taught to smile more often. It was observed by all that she smiled very prettily whenever Mr Ashworth’s carriage was in sight."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **les trois mots qui parlent d’argent** et montrent que le mariage est aussi un marché.","aide":"Cherche ce qu’on reçoit en héritage, ce qu’on gagne et ce qu’on possède.","type":"zone","document":"texte","multiple":true},{"enonce":"Que fait le narrateur avec la phrase « she had agreed with it for three weeks, which is the length of time Mr Ashworth had been in the neighbourhood » ?","aide":"Trois semaines : c’est exactement le temps depuis lequel Mr Ashworth est arrivé.","type":"choix","options":[{"id":"a","texte":"Il note simplement une durée, sans aucun jugement sur elle"},{"id":"b","texte":"Il admire la patience de Mrs Pole, qui attend depuis longtemps"},{"id":"c","texte":"Il se moque de la hâte de Mrs Pole à épouser l’avis du village"},{"id":"d","texte":"Il s’emporte contre l’avis du village tout entier"}],"multiple":false},{"enonce":"Que suggère l’expression « a good heart and no fortune » sur le mariage dans cette société ?","aide":"Regarde ce que la fille doit faire : sourire davantage dès que la voiture du riche apparaît.","type":"choix","options":[{"id":"a","texte":"Un bon cœur pèse moins lourd qu’une fortune pour se marier"},{"id":"b","texte":"L’héroïne refusera d’épouser un homme riche"},{"id":"c","texte":"Les bons cœurs sont très rares dans les petits villages"},{"id":"d","texte":"La fortune vient toujours de la bonté du cœur"}],"multiple":false},{"enonce":"Relie chaque notion du chapitre à sa définition.","aide":"« Entail » est le mot qui explique pourquoi les filles n’héritent pas.","type":"association","gauche":[{"id":"g0","texte":"Irony"},{"id":"g1","texte":"Free indirect speech"},{"id":"g2","texte":"Entail"},{"id":"g3","texte":"Serialisation"}],"droite":[{"id":"d0","texte":"Dire le contraire de ce qu’on affirme"},{"id":"d1","texte":"La publication d’un roman par épisodes"},{"id":"d2","texte":"Une substitution successorale qui prive les filles de l’héritage"},{"id":"d3","texte":"Les pensées d’un personnage rapportées sans verbe introducteur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m36","m78"]},"explication":"**inherited**, **income**, **fortune** : l’argent est au cœur de la conversation du village, bien avant les sentiments."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le narrateur fait comme si l’opinion de Mrs Pole était ancienne, alors qu’elle date de l’arrivée du riche célibataire : c’est de l’**ironie**, qui laisse le lecteur conclure."},{"cle":{"type":"choix","ids":["a"]},"explication":"La jeune fille a des qualités, mais pas d’argent : on lui apprend donc à sourire. Le **mariage est un marché** autant qu’un sentiment."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"**Irony** : dire le contraire ; **free indirect speech** : discours indirect libre ; **entail** : substitution successorale ; **serialisation** : publication en feuilletons."}]$ex$::jsonb),
  ('b504aa24-0f02-59e4-9167-e2d99b083b61'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une gouvernante écrit à son employeur","competence":"analyser-document","situation":"Dans un exposé sur la société victorienne, Yanis croise une lettre imaginée dans l’esprit de *Jane Eyre* et le tableau des romans de Dickens. Il cherche ce qui les rapproche.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"A governess writes","auteur":"Texte écrit pour l’exercice, à la manière de Charlotte Brontë","blocs":["Sir,","I earn twenty pounds a year, and you pay me to teach your daughters, not to agree with you. I came to this house as a governess, poor and unknown, and I will not be treated as a piece of furniture. My wages buy my work. They do not buy my opinions, nor my silence.","I ask only to be spoken to as an equal in conscience, if not in rank.","Yours, E. M."],"source":"Texte écrit pour l’exercice"},{"id":"dickens","type":"tableau","titre":"Three novels by Dickens","colonnes":["Novel","What it accuses"],"lignes":[["Oliver Twist","The workhouses and the fate of orphans"],["Hard Times","The industrial town and utilitarianism"],["Great Expectations","Money that makes a gentleman"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche **les trois mots qui montrent que la narratrice dépend de l’argent d’un employeur**.","aide":"Un verbe pour ce qu’elle gagne, un verbe pour ce qu’on lui verse, un nom pour son salaire.","type":"zone","document":"lettre","multiple":true},{"enonce":"À quel roman des sœurs Brontë cette lettre fait-elle le plus penser ?","aide":"Une héroïne pauvre, gouvernante, exige d’être traitée en égale : lequel des quatre romans est de Charlotte Brontë ?","type":"choix","options":[{"id":"a","texte":"*Wuthering Heights*"},{"id":"b","texte":"*Jane Eyre*"},{"id":"c","texte":"*Great Expectations*"},{"id":"d","texte":"*Pride and Prejudice*"}],"multiple":false},{"enonce":"Qu’est-ce que la lettre et les trois romans de Dickens du tableau ont en commun ?","aide":"Relis les colonnes « What it accuses » : cherche le point commun avec « wages » et « rank ».","type":"choix","options":[{"id":"a","texte":"L’argent et le rang social pèsent sur la vie des héros"},{"id":"b","texte":"Ils sont tous racontés par un narrateur à la première personne"},{"id":"c","texte":"Ils racontent tous un mariage heureux entre deux familles"},{"id":"d","texte":"Ils se passent tous dans un vieux château hanté"}],"multiple":false},{"enonce":"Quel roman de Dickens choisirais-tu pour illustrer chaque situation ?","aide":"Reprends la colonne de droite du tableau pour chacune des trois situations.","type":"association","gauche":[{"id":"g0","texte":"Un enfant orphelin envoyé dans un workhouse"},{"id":"g1","texte":"Une ville d’usines où seuls comptent les faits et le profit"},{"id":"g2","texte":"Un jeune homme dont la fortune fait un gentleman"}],"droite":[{"id":"d0","texte":"Great Expectations"},{"id":"d1","texte":"Hard Times"},{"id":"d2","texte":"Oliver Twist"}]},{"enonce":"Complète la phrase de la conclusion de Yanis.","aide":"La lettre dit : « as an equal in conscience, if not in rank ».","type":"trous","segments":["Dans *Jane Eyre*, l’héroïne exige d’être traitée en ",0," malgré sa ",1,"."],"banque":["richesse","servante","pauvreté","égale","supérieure"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m9","m43"]},"explication":"**earn**, **pay**, **wages** : elle vit de son salaire, donc elle dépend de celui qui l’emploie. C’est ce qui rend sa revendication plus forte."},{"cle":{"type":"choix","ids":["b"]},"explication":"*Jane Eyre* (Charlotte Brontë, 1847) met en scène une héroïne pauvre qui **exige d’être traitée en égale**. *Wuthering Heights* est d’Emily et brise la linéarité du récit."},{"cle":{"type":"choix","ids":["a"]},"explication":"La gouvernante lutte contre la dépendance de l’argent ; Dickens attaque workhouses, industrie et argent qui fabrique un gentleman. Dans tous les cas, **l’argent et la classe sociale** pèsent sur la vie des personnages."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"**Workhouse** : *Oliver Twist* ; **ville industrielle, utilitarisme** : *Hard Times* ; **argent qui fabrique un gentleman** : *Great Expectations*."},{"cle":{"type":"trous","trous":[["egale","egal"],["pauvrete"]]},"affichage":"égale · pauvreté","explication":"L’héroïne exige d’être traitée en **égale** malgré sa **pauvreté** : c’est exactement ce que dit la gouvernante de la lettre."}]$ex$::jsonb),
  ('2400793d-1b62-5816-b488-9a1fa8572d48'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La maison au bout de la route","competence":"analyser-texte","situation":"Mia prépare son premier commentaire en anglais. Avant d’écrire, elle lit un court texte écrit pour l’exercice et repère ce qui permet d’analyser : lexique, temps, étapes.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"The house","auteur":"Texte écrit pour l’exercice","blocs":["The house stood at the end of a cracked road. Its windows were dark and its garden rotten with weeds, and the wind tore at the shutters. Mary, who had come back after ten years, felt nothing at all, or so she told herself."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche **les trois mots du champ lexical de la dégradation**.","aide":"Cherche ce qui est abîmé : une route, un jardin, ce qui pousse sans soin.","type":"zone","document":"texte","multiple":true},{"enonce":"Touche **les deux mots qui disent combien de temps s’est écoulé**.","aide":"Mary est revenue après un certain nombre d’années.","type":"zone","document":"texte","multiple":true},{"enonce":"Range ces trois phrases dans l’ordre d’un paragraphe de commentaire : **what, how, why**.","aide":"D’abord ce que dit le texte, puis par quels moyens, enfin pour quel effet.","type":"ordre","items":[{"id":"a","texte":"The lexical field of decay (“cracked”, “rotten”) makes the house look dead."},{"id":"b","texte":"The reader senses sadness and unease."},{"id":"c","texte":"Mary comes back to the house of her childhood."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m17","m19"]},"explication":"**cracked**, **rotten**, **weeds** forment un champ lexical de la dégradation : c’est le « how » du commentaire, le moyen qui produit l’effet."},{"cle":{"type":"zone","ids":["m33","m34"]},"explication":"**ten years** : c’est un repère de temps. Avant d’analyser, on repère toujours le setting, c’est-à-dire le cadre dans le temps et dans l’espace."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"**What** : Mary revient ; **how** : le champ lexical de la dégradation ; **why** : le lecteur ressent tristesse et malaise. Sauter le « how » donnerait un simple résumé."}]$ex$::jsonb),
  ('2400793d-1b62-5816-b488-9a1fa8572d48'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le brouillon de Sam","competence":"analyser-document","situation":"Sam a écrit un brouillon de commentaire sur le texte de la maison. Son professeur lui demande de repérer les erreurs fréquentes et de reformuler avec les expressions utiles.","documents":[{"id":"brouillon","type":"texte","genre":"recit","titre":"Sam’s draft","auteur":"Brouillon d’élève écrit pour l’exercice","blocs":["In this extract, Mary come back to her house after ten years.","She see a house with dark windows and a rotten garden.","The author is sad and lonely, because he is describing a dead place.","In the text it says that the garden was in a bad state, and then the wind blows."],"source":"Brouillon écrit pour l’exercice"}],"questions":[{"enonce":"Touche **le mot qui confond l’auteur et le narrateur**.","aide":"On ne peut pas déduire l’humeur de l’auteur d’un texte de fiction.","type":"zone","document":"brouillon","multiple":false},{"enonce":"Range chaque phrase du brouillon selon l’erreur principale.","aide":"Les deux premières phrases décrivent ce qui se passe ; la troisième parle de l’auteur ; la quatrième ne cite rien d’exact.","type":"categories","categories":[{"id":"c0","texte":"Raconte au lieu d’analyser"},{"id":"c1","texte":"Confond auteur et narrateur"},{"id":"c2","texte":"Citation absente ou inexacte"}],"items":[{"id":"i0","texte":"« In the text it says that the garden was in a bad state… »"},{"id":"i1","texte":"« She see a house with dark windows and a rotten garden. »"},{"id":"i2","texte":"« Mary come back to her house after ten years. »"},{"id":"i3","texte":"« The author is sad and lonely… »"}]},{"enonce":"Reformule le début d’un vrai commentaire.","aide":"Utilise les expressions du cours : « The text deals with… », « This is emphasised by… », « It could be argued that… ».","type":"trous","segments":["The text ",0," with the return of a woman to her childhood home. This is ",1," by the lexical field of decay. It ",2," be argued that the house mirrors her feelings."],"banque":["could","should","emphasised","emphasise","speaks","deals"]},{"enonce":"Parmi ces phrases tirées du brouillon et de sa correction, laquelle est un bon « how » ?","aide":"Le « how » nomme un procédé précis et s’appuie sur des mots du texte.","type":"choix","options":[{"id":"a","texte":"The lexical field of decay (“dark”, “rotten”) makes it lifeless."},{"id":"b","texte":"Mary comes back to a house she has not seen for ten years."},{"id":"c","texte":"The author is probably a sad person who lives alone."},{"id":"d","texte":"The reader feels uneasy and a little sad for Mary."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Le mot **author** est la faute : le narrateur est une construction de l’auteur. On ne dit pas que l’auteur est triste ; on dit que le **narrateur** crée une atmosphère triste."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les deux premières phrases **racontent** ; la troisième **confond auteur et narrateur** ; la quatrième renvoie au texte sans **citation exacte**. À chaque fois, il manque le « how »."},{"cle":{"type":"trous","trous":[["deals"],["emphasised","emphasized"],["could"]]},"affichage":"deals · emphasised · could","explication":"**deals** (The text deals with…), **emphasised** (This is emphasised by…), **could** (It could be argued that…) : trois expressions utiles pour introduire, appuyer et nuancer."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **how** nomme un procédé (le champ lexical de la dégradation) et cite des mots du texte. La deuxième phrase est un « what », la troisième un « why », la quatrième une confusion auteur-narrateur."}]$ex$::jsonb),
  ('2400793d-1b62-5816-b488-9a1fa8572d48'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"M. Pemberton, le plus généreux de la paroisse","competence":"argumenter","situation":"Léo prépare un commentaire d’un texte satirique écrit pour l’exercice. Il a noté quelques relevés : il doit corriger une citation, relier procédés et effets, puis construire un paragraphe.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"The generous Mr Pemberton","auteur":"Texte écrit pour l’exercice, dans l’esprit d’une satire victorienne","blocs":["Mr Pemberton was the most generous man in the parish. Every Christmas he gave a shilling to the poor, and he counted them carefully, so that none should receive two.","When the winter came and the poor were hungry, he explained at length that hunger was good for the character. He was very warm that night, by the fire."],"source":"Texte écrit pour l’exercice"},{"id":"releves","type":"tableau","titre":"Les relevés de Léo","colonnes":["Procédé noté","Citation relevée"],"lignes":[["Irony","“the most generous man in the parish”"],["Precision of the count","“he gave a shilling to each of the poor”"],["Contrast with the hungry poor","“He was very warm that night, by the fire.”"]],"enteteLignes":true}],"questions":[{"enonce":"Une citation doit être **exacte**. Touche la case où Léo a **déformé** le texte.","aide":"Compare chaque citation avec le texte, mot à mot. Une seule diffère.","type":"zone","document":"releves","multiple":false},{"enonce":"Relie chaque procédé à l’effet qu’il produit dans ce texte.","aide":"Pour chaque procédé, pose la question « pour quel effet ? » : le « why » de l’analyse.","type":"association","gauche":[{"id":"g0","texte":"L’ironie sur « generous »"},{"id":"g1","texte":"Le contraste entre les affamés et le feu"},{"id":"g2","texte":"Le décompte minutieux des pauvres"}],"droite":[{"id":"d0","texte":"La charité réduite à une comptabilité mesquine"},{"id":"d1","texte":"Le lecteur voit l’hypocrisie derrière l’éloge"},{"id":"d2","texte":"L’indignation du lecteur devant l’égoïsme"}]},{"enonce":"Range ces trois phrases dans l’ordre d’un paragraphe de commentaire.","aide":"Un paragraphe suit l’ordre what, how, why.","type":"ordre","items":[{"id":"a","texte":"HOW: He then counts the poor so that none receives two: the praise is contradicted by the facts."},{"id":"b","texte":"WHY: It could be argued that the narrator makes charity look like self-satisfaction."},{"id":"c","texte":"WHAT: The narrator calls Mr Pemberton the most generous man in the parish."}]},{"enonce":"Quel mot décrit le mieux le ton du narrateur ?","aide":"Le narrateur dit « the most generous » mais montre un homme avare : il se moque de la société.","type":"choix","options":[{"id":"a","texte":"Satirical"},{"id":"b","texte":"Nostalgic"},{"id":"c","texte":"Detached"},{"id":"d","texte":"Admiring"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le texte dit « he gave a shilling **to the poor** », et non « to each of the poor ». La citation doit être **exacte, courte et entre guillemets**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"L’**ironie** dévoile l’hypocrisie ; le **contraste** (faim et chaleur du feu) provoque l’indignation ; le **décompte** montre une charité mesquine, réduite à un calcul."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"On commence par **ce que dit** le texte (what), on montre **par quels moyens** (how), puis on conclut sur **l’effet** (why). L’expression « It could be argued that… » introduit une thèse nuancée."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le ton est **satirical** : l’éloge est ironique, et le texte se moque de la fausse charité. Detached (neutre) ne rend pas compte de la moquerie."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 1re (26) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
